-- CounterNest POS Phase 31.9: managed recall cases, receipt outreach tracking, closure controls, and immutable events.

create table if not exists public.finished_product_recall_cases (
  id uuid primary key default gen_random_uuid(),
  case_number bigint generated by default as identity,
  shop_id uuid not null references public.shops(id) on delete cascade,
  finished_batch_id uuid not null references public.finished_product_batches(id) on delete restrict,
  status text not null default 'open' check(status in('open','closed')),
  recall_reason text not null,
  opened_at timestamptz not null default now(),
  opened_by uuid references auth.users(id) on delete restrict,
  resolution_note text,
  closed_at timestamptz,
  closed_by uuid references auth.users(id) on delete restrict,
  unique(finished_batch_id),
  constraint recall_case_close_fields check((status='open' and closed_at is null and closed_by is null) or(status='closed' and closed_at is not null and closed_by is not null and resolution_note is not null))
);

create table if not exists public.finished_product_recall_actions (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id) on delete cascade,
  case_id uuid not null references public.finished_product_recall_cases(id) on delete restrict,
  sale_id uuid not null references public.sales(id) on delete restrict,
  receipt_number bigint not null,
  customer_id uuid references public.customers(id) on delete set null,
  customer_name_snapshot text not null,
  customer_email_snapshot text,
  customer_phone_snapshot text,
  quantity_at_open numeric(12,3) not null check(quantity_at_open>0),
  status text not null check(status in('pending','contacted','unreachable','resolved','receipt_only')),
  note text,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete restrict,
  unique(case_id,sale_id)
);

create index if not exists finished_recall_actions_case_idx on public.finished_product_recall_actions(case_id,status,receipt_number);

create table if not exists public.finished_product_recall_case_events (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id) on delete cascade,
  case_id uuid not null references public.finished_product_recall_cases(id) on delete restrict,
  action text not null check(action in('opened','outreach_updated','disposed','closed')),
  details jsonb not null default '{}'::jsonb,
  performed_by uuid references auth.users(id) on delete restrict,
  created_at timestamptz not null default now()
);

create index if not exists finished_recall_case_events_idx on public.finished_product_recall_case_events(case_id,created_at desc);

alter table public.finished_product_recall_cases enable row level security;
alter table public.finished_product_recall_actions enable row level security;
alter table public.finished_product_recall_case_events enable row level security;
drop policy if exists finished_recall_cases_admin_select on public.finished_product_recall_cases;
create policy finished_recall_cases_admin_select on public.finished_product_recall_cases for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
drop policy if exists finished_recall_actions_admin_select on public.finished_product_recall_actions;
create policy finished_recall_actions_admin_select on public.finished_product_recall_actions for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
drop policy if exists finished_recall_case_events_admin_select on public.finished_product_recall_case_events;
create policy finished_recall_case_events_admin_select on public.finished_product_recall_case_events for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create or replace function public.open_finished_product_recall_case(p_finished_batch_id uuid,p_reason text,p_performed_by uuid) returns uuid
language plpgsql security definer set search_path=public as $$
declare v_batch public.finished_product_batches%rowtype;v_case uuid;
begin
  select * into v_batch from public.finished_product_batches where id=p_finished_batch_id;
  if v_batch.id is null then raise exception 'Finished-product batch not found'; end if;
  insert into public.finished_product_recall_cases(shop_id,finished_batch_id,recall_reason,opened_by)
  values(v_batch.shop_id,v_batch.id,trim(p_reason),p_performed_by)
  on conflict(finished_batch_id) do update set recall_reason=excluded.recall_reason
  returning id into v_case;
  insert into public.finished_product_recall_actions(shop_id,case_id,sale_id,receipt_number,customer_id,customer_name_snapshot,customer_email_snapshot,customer_phone_snapshot,quantity_at_open,status,updated_by)
  select v_batch.shop_id,v_case,s.id,s.receipt_number,s.customer_id,coalesce(c.name,s.customer_name_snapshot,'Guest'),coalesce(c.email,s.customer_email_snapshot),c.phone,sum(a.quantity_allocated-a.quantity_returned),case when coalesce(c.email,s.customer_email_snapshot) is null and c.phone is null then 'receipt_only' else 'pending' end,p_performed_by
  from public.finished_product_batch_sale_allocations a join public.sales s on s.id=a.sale_id left join public.customers c on c.id=s.customer_id
  where a.finished_batch_id=v_batch.id and a.quantity_allocated>a.quantity_returned
  group by s.id,s.receipt_number,s.customer_id,c.name,s.customer_name_snapshot,c.email,s.customer_email_snapshot,c.phone
  on conflict(case_id,sale_id) do nothing;
  if not exists(select 1 from public.finished_product_recall_case_events where case_id=v_case and action='opened') then
    insert into public.finished_product_recall_case_events(shop_id,case_id,action,details,performed_by)
    values(v_batch.shop_id,v_case,'opened',jsonb_build_object('finished_batch_id',v_batch.id,'batch_code',v_batch.batch_code,'reason',trim(p_reason)),p_performed_by);
  end if;
  return v_case;
end $$;

-- Backfill a managed case for any batch recalled before Phase 31.9.
do $$
declare row record;v_case uuid;
begin
  for row in select id,coalesce(recall_reason,'Recalled before Phase 31.9') reason from public.finished_product_batches where status='recalled' loop
    v_case:=public.open_finished_product_recall_case(row.id,row.reason,null);
  end loop;
end $$;

create or replace function public.recall_finished_product_batch(p_finished_batch_id uuid,p_reason text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_batch public.finished_product_batches%rowtype;v_product uuid;v_sales integer;v_customers integer;v_case uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'A recall reason of at least 5 characters is required'; end if;
  select product_id into v_product from public.finished_product_batches where id=p_finished_batch_id and shop_id=v_shop;
  if v_product is null then raise exception 'Finished-product batch not found'; end if;
  perform 1 from public.products where id=v_product and shop_id=v_shop for update;
  select * into v_batch from public.finished_product_batches where id=p_finished_batch_id and shop_id=v_shop for update;
  if v_batch.status='recalled' then raise exception 'Finished-product batch is already recalled'; end if;
  update public.products set stock=greatest(0,stock-v_batch.remaining_quantity),updated_at=now() where id=v_batch.product_id and shop_id=v_shop;
  update public.finished_product_batches set status='recalled',recall_reason=trim(p_reason),updated_at=now() where id=v_batch.id;
  insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
  values(v_shop,v_batch.id,'recalled',v_batch.remaining_quantity,jsonb_build_object('reason',trim(p_reason),'quarantined_quantity',v_batch.remaining_quantity),auth.uid());
  v_case:=public.open_finished_product_recall_case(v_batch.id,trim(p_reason),auth.uid());
  select count(distinct a.sale_id),count(distinct s.customer_id) filter(where s.customer_id is not null) into v_sales,v_customers from public.finished_product_batch_sale_allocations a join public.sales s on s.id=a.sale_id where a.finished_batch_id=v_batch.id and a.quantity_allocated>a.quantity_returned;
  return jsonb_build_object('finished_batch_id',v_batch.id,'recall_case_id',v_case,'quarantined_quantity',v_batch.remaining_quantity,'affected_sales',v_sales,'identified_customers',v_customers);
end $$;

create or replace function public.update_finished_product_recall_action(p_action_id uuid,p_status text,p_note text) returns void
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_action public.finished_product_recall_actions%rowtype;v_case_status text;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_status not in('pending','contacted','unreachable','resolved','receipt_only') then raise exception 'Invalid recall action status'; end if;
  select a.* into v_action
  from public.finished_product_recall_actions a
  join public.finished_product_recall_cases c on c.id=a.case_id
  where a.id=p_action_id and a.shop_id=v_shop
  for update of a,c;
  if v_action.id is null then raise exception 'Recall receipt action not found'; end if;
  select status into v_case_status from public.finished_product_recall_cases where id=v_action.case_id and shop_id=v_shop;
  if v_case_status<>'open' then raise exception 'Closed recall cases cannot be changed'; end if;
  if p_status in('contacted','unreachable','resolved') and length(trim(coalesce(p_note,'')))<3 then raise exception 'Add a note describing the contact attempt or outcome'; end if;
  update public.finished_product_recall_actions set status=p_status,note=nullif(trim(p_note),''),updated_at=now(),updated_by=auth.uid() where id=v_action.id;
  insert into public.finished_product_recall_case_events(shop_id,case_id,action,details,performed_by)
  values(v_shop,v_action.case_id,'outreach_updated',jsonb_build_object('action_id',v_action.id,'sale_id',v_action.sale_id,'receipt_number',v_action.receipt_number,'old_status',v_action.status,'status',p_status,'note',nullif(trim(p_note),'')),auth.uid());
end $$;

create or replace function public.close_finished_product_recall_case(p_case_id uuid,p_resolution_note text) returns void
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_case public.finished_product_recall_cases%rowtype;v_remaining numeric;v_pending integer;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if length(trim(coalesce(p_resolution_note,'')))<5 then raise exception 'A resolution note of at least 5 characters is required'; end if;
  select * into v_case from public.finished_product_recall_cases where id=p_case_id and shop_id=v_shop for update;
  if v_case.id is null or v_case.status<>'open' then raise exception 'Open recall case not found'; end if;
  select remaining_quantity into v_remaining from public.finished_product_batches where id=v_case.finished_batch_id for update;
  select count(*) into v_pending from public.finished_product_recall_actions where case_id=v_case.id and status='pending';
  if v_remaining>0 then raise exception 'Dispose all quarantined batch quantity before closing the recall case'; end if;
  if v_pending>0 then raise exception 'Resolve all pending receipt/contact actions before closing the recall case'; end if;
  update public.finished_product_recall_cases set status='closed',resolution_note=trim(p_resolution_note),closed_at=now(),closed_by=auth.uid() where id=v_case.id;
  insert into public.finished_product_recall_case_events(shop_id,case_id,action,details,performed_by)
  values(v_shop,v_case.id,'closed',jsonb_build_object('resolution_note',trim(p_resolution_note)),auth.uid());
end $$;

create or replace function public.dispose_finished_product_batch(p_finished_batch_id uuid,p_quantity numeric,p_note text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_batch public.finished_product_batches%rowtype;v_case uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_quantity is null or p_quantity<=0 then raise exception 'Disposal quantity must be greater than zero'; end if;
  if length(trim(coalesce(p_note,'')))<3 then raise exception 'A disposal note of at least 3 characters is required'; end if;
  select * into v_batch from public.finished_product_batches where id=p_finished_batch_id and shop_id=v_shop for update;
  if v_batch.id is null or v_batch.status<>'recalled' then raise exception 'Recall the finished-product batch before disposal'; end if;
  if p_quantity>v_batch.remaining_quantity then raise exception 'Disposal exceeds quarantined batch quantity'; end if;
  update public.finished_product_batches set remaining_quantity=remaining_quantity-p_quantity,updated_at=now() where id=v_batch.id;
  insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
  values(v_shop,v_batch.id,'disposed',p_quantity,jsonb_build_object('note',trim(p_note)),auth.uid());
  select id into v_case from public.finished_product_recall_cases where finished_batch_id=v_batch.id;
  if v_case is not null then
    insert into public.finished_product_recall_case_events(shop_id,case_id,action,details,performed_by)
    values(v_shop,v_case,'disposed',jsonb_build_object('quantity',p_quantity,'note',trim(p_note),'remaining_quarantined',v_batch.remaining_quantity-p_quantity),auth.uid());
  end if;
  return jsonb_build_object('finished_batch_id',v_batch.id,'remaining_quarantined',v_batch.remaining_quantity-p_quantity,'estimated_cost',round(p_quantity*v_batch.unit_cost_snapshot,2));
end $$;

create or replace function public.get_finished_product_recall_cases() returns jsonb
language plpgsql security definer stable set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  return jsonb_build_object(
    'summary',(select jsonb_build_object('open_cases',count(*) filter(where status='open'),'closed_cases',count(*) filter(where status='closed'),'pending_actions',(select count(*) from public.finished_product_recall_actions a join public.finished_product_recall_cases c2 on c2.id=a.case_id where c2.shop_id=v_shop and c2.status='open' and a.status='pending'),'quarantined_units',(select coalesce(sum(b.remaining_quantity),0) from public.finished_product_batches b join public.finished_product_recall_cases c3 on c3.finished_batch_id=b.id where c3.shop_id=v_shop and c3.status='open')) from public.finished_product_recall_cases where shop_id=v_shop),
    'cases',(select coalesce(jsonb_agg(to_jsonb(x) order by(case when x.status='open' then 0 else 1 end),x.opened_at desc),'[]'::jsonb) from(
      select c.id,c.case_number,c.status,c.recall_reason,c.opened_at,c.resolution_note,c.closed_at,b.id finished_batch_id,b.batch_code,b.product_id,p.name product_name,b.remaining_quantity quarantined_quantity,b.produced_quantity,b.best_before_on,
        coalesce(op.display_name,'System migration') opened_by_name,cl.display_name closed_by_name,
        (select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'sale_id',a.sale_id,'receipt_number',a.receipt_number,'sale_status',s.status,'sold_at',s.created_at,'customer_id',a.customer_id,'customer_name',a.customer_name_snapshot,'customer_email',a.customer_email_snapshot,'customer_phone',a.customer_phone_snapshot,'quantity_at_open',a.quantity_at_open,'current_net_quantity',coalesce((select sum(sa.quantity_allocated-sa.quantity_returned) from public.finished_product_batch_sale_allocations sa where sa.finished_batch_id=b.id and sa.sale_id=a.sale_id),0),'status',a.status,'note',a.note,'updated_at',a.updated_at,'updated_by_name',up.display_name) order by a.receipt_number),'[]'::jsonb) from public.finished_product_recall_actions a join public.sales s on s.id=a.sale_id left join public.staff_profiles up on up.user_id=a.updated_by and up.shop_id=a.shop_id where a.case_id=c.id) actions,
        (select coalesce(jsonb_agg(jsonb_build_object('created_at',e.created_at,'action',e.action,'details',e.details,'performed_by_name',coalesce(ep.display_name,'System migration')) order by e.created_at desc),'[]'::jsonb) from public.finished_product_recall_case_events e left join public.staff_profiles ep on ep.user_id=e.performed_by and ep.shop_id=e.shop_id where e.case_id=c.id) events
      from public.finished_product_recall_cases c join public.finished_product_batches b on b.id=c.finished_batch_id join public.products p on p.id=b.product_id left join public.staff_profiles op on op.user_id=c.opened_by and op.shop_id=c.shop_id left join public.staff_profiles cl on cl.user_id=c.closed_by and cl.shop_id=c.shop_id where c.shop_id=v_shop
    )x)
  );
end $$;

revoke all on function public.open_finished_product_recall_case(uuid,text,uuid) from public;
revoke all on function public.recall_finished_product_batch(uuid,text) from public;
revoke all on function public.update_finished_product_recall_action(uuid,text,text) from public;
revoke all on function public.close_finished_product_recall_case(uuid,text) from public;
revoke all on function public.dispose_finished_product_batch(uuid,numeric,text) from public;
revoke all on function public.get_finished_product_recall_cases() from public;
grant execute on function public.recall_finished_product_batch(uuid,text) to authenticated;
grant execute on function public.update_finished_product_recall_action(uuid,text,text) to authenticated;
grant execute on function public.close_finished_product_recall_case(uuid,text) to authenticated;
grant execute on function public.dispose_finished_product_batch(uuid,numeric,text) to authenticated;
grant execute on function public.get_finished_product_recall_cases() to authenticated;

-- Include the complete recall-case record in the administrator backup addendum.
create or replace function public.export_supply_operations_backup() returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  return jsonb_build_object(
    'schema_version','1.11.0','exported_at',now(),'shop_id',v_shop,
    'ingredient_purchase_orders',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_orders t where shop_id=v_shop),
    'ingredient_purchase_order_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_order_items t where shop_id=v_shop),
    'ingredient_purchase_order_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_order_events t where shop_id=v_shop),
    'ingredient_purchase_receipts',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_receipts t where shop_id=v_shop),
    'ingredient_purchase_receipt_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_receipt_items t where shop_id=v_shop),
    'inventory_waste_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.inventory_waste_events t where shop_id=v_shop),
    'ingredient_lots',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_lots t where shop_id=v_shop),
    'ingredient_lot_allocations',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_lot_allocations t where shop_id=v_shop),
    'ingredient_lot_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_lot_events t where shop_id=v_shop),
    'finished_product_batches',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.finished_product_batches t where shop_id=v_shop),
    'finished_product_batch_sale_allocations',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.finished_product_batch_sale_allocations t where shop_id=v_shop),
    'finished_product_batch_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.finished_product_batch_events t where shop_id=v_shop),
    'finished_product_recall_cases',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.finished_product_recall_cases t where shop_id=v_shop),
    'finished_product_recall_actions',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.finished_product_recall_actions t where shop_id=v_shop),
    'finished_product_recall_case_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.finished_product_recall_case_events t where shop_id=v_shop)
  );
end $$;

-- Phase 31.9 acceptance preserves the existing safety checks and adds recall-case readiness.
create or replace function public.run_phase31_operational_acceptance(p_notes text default null) returns jsonb
language plpgsql security definer set search_path=public as $$
declare
  v_shop uuid:=public.current_shop_id();v_admins integer;v_products integer;v_negative integer;v_empty_recipes integer;v_invalid_recipe_items integer;v_overdue_batches integer;v_uncosted integer;v_recent_backup boolean;v_invalid_orders integer;v_overdue_orders integer;v_lot_gaps integer;v_expired integer;v_recalled integer;v_finished_gaps integer;v_finished_expired integer;v_finished_recalled integer;v_open_recall_cases integer;v_pending_recall_actions integer;v_checks jsonb;v_status text;v_id uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  select count(*) into v_admins from public.staff_profiles where shop_id=v_shop and active and role='admin';
  select count(*) into v_products from public.products where shop_id=v_shop and active;
  select count(*) into v_negative from public.ingredients where shop_id=v_shop and current_quantity<0;
  select count(*) into v_empty_recipes from public.product_recipes pr where pr.shop_id=v_shop and pr.active and not exists(select 1 from public.recipe_items ri where ri.recipe_id=pr.id);
  select count(*) into v_invalid_recipe_items from public.recipe_items ri join public.product_recipes pr on pr.id=ri.recipe_id join public.ingredients i on i.id=ri.ingredient_id where pr.shop_id=v_shop and(ri.shop_id<>v_shop or i.shop_id<>v_shop or not i.active);
  select count(*) into v_overdue_batches from public.production_batches where shop_id=v_shop and status='scheduled' and scheduled_date<current_date;
  select count(*) into v_uncosted from public.products where shop_id=v_shop and active and coalesce(cost_price,0)=0;
  select exists(select 1 from public.backup_exports where shop_id=v_shop and requested_at>=now()-interval '30 days') into v_recent_backup;
  select count(*) into v_invalid_orders from public.ingredient_purchase_orders po join public.suppliers s on s.id=po.supplier_id where po.shop_id=v_shop and po.status in('ordered','partially_received') and(not s.active or not exists(select 1 from public.ingredient_purchase_order_items i where i.order_id=po.id));
  select count(*) into v_overdue_orders from public.ingredient_purchase_orders where shop_id=v_shop and status in('ordered','partially_received') and expected_date<current_date;
  select count(*) into v_lot_gaps from public.ingredients i where i.shop_id=v_shop and abs(i.current_quantity-coalesce((select sum(l.remaining_quantity) from public.ingredient_lots l where l.ingredient_id=i.id),0))>0.001;
  select count(*) into v_expired from public.ingredient_lots where shop_id=v_shop and status='active' and remaining_quantity>0 and expires_on<current_date;
  select count(*) into v_recalled from public.ingredient_lots where shop_id=v_shop and status='recalled' and remaining_quantity>0;
  select count(*) into v_finished_gaps from public.products p where p.shop_id=v_shop and abs(p.stock-coalesce((select sum(b.remaining_quantity) from public.finished_product_batches b where b.product_id=p.id and b.status='active'),0))>0.001;
  select count(*) into v_finished_expired from public.finished_product_batches where shop_id=v_shop and status='active' and remaining_quantity>0 and best_before_on<current_date;
  select count(*) into v_finished_recalled from public.finished_product_batches where shop_id=v_shop and status='recalled';
  select count(*) into v_open_recall_cases from public.finished_product_recall_cases where shop_id=v_shop and status='open';
  select count(*) into v_pending_recall_actions from public.finished_product_recall_actions a join public.finished_product_recall_cases c on c.id=a.case_id where c.shop_id=v_shop and c.status='open' and a.status='pending';
  v_checks:=jsonb_build_array(
    jsonb_build_object('id','active_admin','label','At least one active administrator','status',case when v_admins>0 then 'pass' else 'fail' end,'required',true,'detail',v_admins||' active administrator(s)'),
    jsonb_build_object('id','active_products','label','Active product catalog','status',case when v_products>0 then 'pass' else 'fail' end,'required',true,'detail',v_products||' active product(s)'),
    jsonb_build_object('id','ingredient_balances','label','No negative ingredient balances','status',case when v_negative=0 then 'pass' else 'fail' end,'required',true,'detail',v_negative||' invalid balance(s)'),
    jsonb_build_object('id','recipe_items','label','Active recipes contain ingredients','status',case when v_empty_recipes=0 then 'pass' else 'fail' end,'required',true,'detail',v_empty_recipes||' empty active recipe(s)'),
    jsonb_build_object('id','recipe_scope','label','Recipe ingredients are active and shop-scoped','status',case when v_invalid_recipe_items=0 then 'pass' else 'fail' end,'required',true,'detail',v_invalid_recipe_items||' invalid recipe line(s)'),
    jsonb_build_object('id','supply_orders','label','Open ingredient orders have active suppliers and lines','status',case when v_invalid_orders=0 then 'pass' else 'fail' end,'required',true,'detail',v_invalid_orders||' invalid open order(s)'),
    jsonb_build_object('id','lot_ledger','label','Ingredient lot totals match inventory balances','status',case when v_lot_gaps=0 then 'pass' else 'fail' end,'required',true,'detail',v_lot_gaps||' ingredient lot mismatch(es)'),
    jsonb_build_object('id','finished_batch_ledger','label','Active finished-batch totals match sellable product stock','status',case when v_finished_gaps=0 then 'pass' else 'fail' end,'required',true,'detail',v_finished_gaps||' finished-product batch mismatch(es)'),
    jsonb_build_object('id','recent_backup','label','Verified backup created in the last 30 days','status',case when v_recent_backup then 'pass' else 'fail' end,'required',true,'detail',case when v_recent_backup then 'Recent backup record found' else 'Create and verify a fresh backup' end),
    jsonb_build_object('id','expired_lots','label','No expired ingredient stock remains available','status',case when v_expired=0 then 'pass' else 'warning' end,'required',false,'detail',v_expired||' expired ingredient lot(s) require disposal'),
    jsonb_build_object('id','recalled_lots','label','No recalled ingredient stock remains available','status',case when v_recalled=0 then 'pass' else 'warning' end,'required',false,'detail',v_recalled||' recalled ingredient lot(s) require disposition'),
    jsonb_build_object('id','expired_finished_batches','label','No expired finished-product batch stock remains available','status',case when v_finished_expired=0 then 'pass' else 'warning' end,'required',false,'detail',v_finished_expired||' expired finished batch(es) require recall review'),
    jsonb_build_object('id','recalled_finished_batches','label','Finished-product recalls have been reviewed','status',case when v_finished_recalled=0 then 'pass' else 'warning' end,'required',false,'detail',v_finished_recalled||' recalled finished batch(es) remain in trace history'),
    jsonb_build_object('id','open_recall_cases','label','Finished-product recall cases are resolved','status',case when v_open_recall_cases=0 then 'pass' else 'warning' end,'required',false,'detail',v_open_recall_cases||' open recall case(s)'),
    jsonb_build_object('id','pending_recall_actions','label','Affected receipt actions have outcomes','status',case when v_pending_recall_actions=0 then 'pass' else 'warning' end,'required',false,'detail',v_pending_recall_actions||' pending receipt action(s)'),
    jsonb_build_object('id','overdue_batches','label','No overdue scheduled production','status',case when v_overdue_batches=0 then 'pass' else 'warning' end,'required',false,'detail',v_overdue_batches||' overdue batch(es)'),
    jsonb_build_object('id','overdue_supply','label','No overdue ingredient deliveries','status',case when v_overdue_orders=0 then 'pass' else 'warning' end,'required',false,'detail',v_overdue_orders||' overdue ingredient order(s)'),
    jsonb_build_object('id','product_costs','label','Active products have a unit cost','status',case when v_uncosted=0 then 'pass' else 'warning' end,'required',false,'detail',v_uncosted||' uncosted product(s)')
  );
  v_status:=case when v_admins=0 or v_products=0 or v_negative>0 or v_empty_recipes>0 or v_invalid_recipe_items>0 or v_invalid_orders>0 or v_lot_gaps>0 or v_finished_gaps>0 or not v_recent_backup then 'failed' when v_expired>0 or v_recalled>0 or v_finished_expired>0 or v_finished_recalled>0 or v_open_recall_cases>0 or v_pending_recall_actions>0 or v_overdue_batches>0 or v_overdue_orders>0 or v_uncosted>0 then 'warning' else 'passed' end;
  insert into public.operational_acceptance_runs(shop_id,release_version,phase,status,checks,notes,run_by) values(v_shop,'1.11.0','31.9',v_status,v_checks,nullif(trim(p_notes),''),auth.uid()) returning id into v_id;
  return jsonb_build_object('id',v_id,'release_version','1.11.0','phase','31.9','status',v_status,'checks',v_checks,'notes',nullif(trim(p_notes),''),'run_at',now());
end $$;

revoke all on function public.export_supply_operations_backup() from public;
revoke all on function public.run_phase31_operational_acceptance(text) from public;
grant execute on function public.export_supply_operations_backup() to authenticated;
grant execute on function public.run_phase31_operational_acceptance(text) to authenticated;
